"use client";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { CopyText } from "@/components/ui/copy-text";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Loader } from "@/components/ui/loader";
import { type ReactNode, useEffect, useId, useRef, useState } from "react";

export interface DeleteResourceProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  resourceType: string;
  resourceName: string;
  onDelete: () => void | Promise<void>;
  isDeleting?: boolean;
  caseSensitive?: boolean;
  errorMessage?: string;
  description?: ReactNode;
  className?: string;
  labels?: Partial<{
    title: string;
    description: string;
    confirmation: string;
    hint: string;
    cancel: string;
    delete: string;
    deleting: string;
    failed: string;
    copy: string;
    copying: string;
    copied: string;
    copyFailed: string;
  }>;
}

/** Requires an exact resource name and stays open if the delete callback fails. */
export function DeleteResource(props: DeleteResourceProps) {
  // Each opening and resource gets a fresh confirmation and error state.
  return (
    <DeleteResourceDialog
      key={`${props.resourceType}:${props.resourceName}:${props.open}`}
      {...props}
    />
  );
}

function DeleteResourceDialog({
  open,
  onOpenChange,
  resourceType,
  resourceName,
  onDelete,
  isDeleting = false,
  caseSensitive = true,
  errorMessage,
  description,
  className,
  labels: overrides,
}: DeleteResourceProps) {
  const id = useId();
  const [confirmation, setConfirmation] = useState("");
  const [pending, setPending] = useState(false);
  const [error, setError] = useState("");
  const inFlight = useRef(false);
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  const labels = {
    title: `Delete ${resourceType}?`,
    description: `This will permanently delete ${resourceName}. This action cannot be undone.`,
    confirmation: "Resource name",
    hint: `Type ${resourceName} to confirm.`,
    cancel: "Cancel",
    delete: `Delete ${resourceType}`,
    deleting: "Deleting…",
    failed: "Unable to delete this resource. Please try again.",
    copy: "Copy resource name",
    copying: "Copying…",
    copied: "Copied",
    copyFailed: "Copy failed. Select and copy the name manually.",
    ...overrides,
  };
  const busy = pending || isDeleting;
  const matches =
    resourceName.length > 0 &&
    (caseSensitive
      ? confirmation === resourceName
      : confirmation.toLocaleLowerCase() === resourceName.toLocaleLowerCase());
  const failure = errorMessage || error;
  let hintNameIndex = -1;
  if (resourceName) {
    hintNameIndex =
      overrides?.hint === undefined
        ? "Type ".length
        : labels.hint.indexOf(resourceName);
  }

  async function handleDelete(event: React.FormEvent) {
    event.preventDefault();
    if (!matches || busy || inFlight.current) return;
    inFlight.current = true;
    setPending(true);
    setError("");
    try {
      await onDelete();
      if (mounted.current) onOpenChange(false);
    } catch (cause) {
      if (mounted.current)
        setError(cause instanceof Error ? cause.message : labels.failed);
    } finally {
      inFlight.current = false;
      if (mounted.current) setPending(false);
    }
  }

  return (
    <AlertDialog
      open={open}
      onOpenChange={(next) => {
        if (!busy) onOpenChange(next);
      }}
    >
      <AlertDialogContent className={className}>
        <AlertDialogHeader>
          <AlertDialogTitle>{labels.title}</AlertDialogTitle>
          <AlertDialogDescription>
            {description ?? labels.description}
          </AlertDialogDescription>
        </AlertDialogHeader>
        <form
          onSubmit={handleDelete}
          className="flex flex-col gap-6"
          aria-busy={busy}
        >
          <FieldGroup>
            <Field data-invalid={!!failure} data-disabled={busy}>
              <FieldLabel htmlFor={id}>{labels.confirmation}</FieldLabel>
              <Input
                id={id}
                value={confirmation}
                onChange={(event) => setConfirmation(event.target.value)}
                disabled={busy}
                autoComplete="off"
                spellCheck={false}
                aria-invalid={!!failure}
                aria-describedby={`${id}-hint${failure ? ` ${id}-error` : ""}`}
              />
              <FieldDescription id={`${id}-hint`}>
                {resourceName ? (
                  <>
                    {hintNameIndex >= 0
                      ? labels.hint.slice(0, hintNameIndex)
                      : `${labels.hint} `}
                    <CopyText
                      iconVisibility="always"
                      value={resourceName}
                      disabled={busy}
                      labels={{
                        copy: labels.copy,
                        pending: labels.copying,
                        copied: labels.copied,
                        copyFailed: labels.copyFailed,
                      }}
                    >
                      {resourceName}
                    </CopyText>
                    {hintNameIndex >= 0 &&
                      labels.hint.slice(hintNameIndex + resourceName.length)}
                  </>
                ) : (
                  labels.hint
                )}
              </FieldDescription>
              {failure && <FieldError id={`${id}-error`}>{failure}</FieldError>}
            </Field>
          </FieldGroup>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={busy}>
              {labels.cancel}
            </AlertDialogCancel>
            <AlertDialogAction
              type="submit"
              variant="destructive"
              disabled={!matches || busy}
            >
              {busy && (
                <Loader data-icon="inline-start" label={labels.deleting} />
              )}
              {busy ? labels.deleting : labels.delete}
            </AlertDialogAction>
          </AlertDialogFooter>
        </form>
      </AlertDialogContent>
    </AlertDialog>
  );
}

"use client";

import { useForm } from "@tanstack/react-form";
import {
  Alert,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Loader } from "@/components/ui/loader";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectList,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useId, useState } from "react";
import { z } from "zod";

export interface BugReportValues {
  title: string;
  description: string;
}
export interface ProfileValues {
  name: string;
  email: string;
  role: string;
  notifications: boolean;
}
/** Text shared by form feedback and submission controls. */
export interface FormFeedbackLabels {
  failed: string;
  saved: string;
  savedDescription: string;
  submitError: string;
  submitting: string;
  reset: string;
}

const defaultFormFeedbackLabels: FormFeedbackLabels = {
  failed: "Submission failed",
  saved: "Saved",
  savedDescription: "Your changes have been submitted.",
  submitError: "Please try again.",
  submitting: "Submitting…",
  reset: "Reset",
};

export interface BugReportFormLabels extends FormFeedbackLabels {
  formTitle: string;
  formDescription: string;
  title: string;
  titlePlaceholder: string;
  description: string;
  descriptionHint: string;
  titleMinLength: string;
  titleMaxLength: string;
  descriptionMinLength: string;
  descriptionMaxLength: string;
  submit: string;
}

export const defaultBugReportFormLabels: BugReportFormLabels = {
  ...defaultFormFeedbackLabels,
  formTitle: "Bug report",
  formDescription: "Tell us what happened so we can improve the product.",
  title: "Title",
  titlePlaceholder: "Login button does not work on mobile",
  description: "Description",
  descriptionHint:
    "Include steps to reproduce, expected behavior, and actual results.",
  titleMinLength: "Title must be at least 5 characters.",
  titleMaxLength: "Title must be at most 80 characters.",
  descriptionMinLength: "Description must be at least 20 characters.",
  descriptionMaxLength: "Description must be at most 500 characters.",
  submit: "Submit report",
};

export interface ProfileFormLabels extends FormFeedbackLabels {
  formTitle: string;
  formDescription: string;
  name: string;
  email: string;
  role: string;
  rolePlaceholder: string;
  designerRole: string;
  developerRole: string;
  managerRole: string;
  notifications: string;
  nameMinLength: string;
  nameMaxLength: string;
  invalidEmail: string;
  invalidRole: string;
  submit: string;
}

export const defaultProfileFormLabels: ProfileFormLabels = {
  ...defaultFormFeedbackLabels,
  formTitle: "Profile settings",
  formDescription: "Update your details and notification preferences.",
  name: "Name",
  email: "Email",
  role: "Role",
  rolePlaceholder: "Choose a role",
  designerRole: "Designer",
  developerRole: "Developer",
  managerRole: "Manager",
  notifications: "Email me product updates",
  nameMinLength: "Name must be at least 2 characters.",
  nameMaxLength: "Name must be at most 50 characters.",
  invalidEmail: "Enter a valid email address.",
  invalidRole: "Choose a role.",
  submit: "Save profile",
};

export interface FormBlockProps<T, TLabels = FormFeedbackLabels> {
  initialValues?: Partial<T>;
  onSubmit: (values: T) => void | Promise<void>;
  labels?: Partial<TLabels>;
  className?: string;
}

function useSubmission<T>(
  onSubmit: FormBlockProps<T>["onSubmit"],
  fallback: string,
) {
  const [feedback, setFeedback] = useState<{ error?: string; saved?: boolean }>(
    {},
  );
  async function submit(values: T) {
    setFeedback({});
    try {
      await onSubmit(values);
      setFeedback({ saved: true });
    } catch (error) {
      setFeedback({ error: error instanceof Error ? error.message : fallback });
    }
  }
  return { feedback, submit, reset: () => setFeedback({}) };
}

function FormFeedback({
  feedback,
  labels,
}: {
  feedback: { error?: string; saved?: boolean };
  labels: FormFeedbackLabels;
}) {
  if (!feedback.error && !feedback.saved) return null;
  return (
    <Alert
      variant={feedback.error ? "destructive" : "default"}
      role={feedback.error ? "alert" : "status"}
    >
      <AlertTitle>{feedback.error ? labels.failed : labels.saved}</AlertTitle>
      <AlertDescription>
        {feedback.error ?? labels.savedDescription}
      </AlertDescription>
    </Alert>
  );
}

/** A validated report form with asynchronous submission and reset controls. */
export function BugReportForm({
  initialValues,
  onSubmit,
  labels: overrides,
  className,
}: FormBlockProps<BugReportValues, BugReportFormLabels>) {
  const labels = { ...defaultBugReportFormLabels, ...overrides };
  const id = useId();
  const schema = z.object({
    title: z
      .string()
      .trim()
      .min(5, labels.titleMinLength)
      .max(80, labels.titleMaxLength),
    description: z
      .string()
      .trim()
      .min(20, labels.descriptionMinLength)
      .max(500, labels.descriptionMaxLength),
  });
  const submission = useSubmission(onSubmit, labels.submitError);
  const form = useForm({
    defaultValues: { title: "", description: "", ...initialValues },
    validators: { onBlur: schema, onSubmit: schema },
    onSubmit: async ({ value }) => submission.submit(schema.parse(value)),
  });
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>{labels.formTitle}</CardTitle>
        <CardDescription>{labels.formDescription}</CardDescription>
      </CardHeader>
      <CardContent>
        <form
          id={id}
          noValidate
          onSubmit={(event) => {
            event.preventDefault();
            void form.handleSubmit();
          }}
        >
          <form.Subscribe selector={(state) => state.isSubmitting}>
            {(pending) => (
              <FieldGroup>
                <form.Field name="title">
                  {(field) => {
                    const invalid =
                      field.state.meta.isTouched && !field.state.meta.isValid;
                    return (
                      <Field data-invalid={invalid} data-disabled={pending}>
                        <FieldLabel htmlFor={`${id}-title`}>
                          {labels.title}
                        </FieldLabel>
                        <Input
                          id={`${id}-title`}
                          name={field.name}
                          value={field.state.value}
                          disabled={pending}
                          onBlur={field.handleBlur}
                          onChange={(event) =>
                            field.handleChange(event.target.value)
                          }
                          aria-invalid={invalid}
                          aria-describedby={
                            invalid ? `${id}-title-error` : undefined
                          }
                          placeholder={labels.titlePlaceholder}
                          autoComplete="off"
                        />
                        {invalid && (
                          <FieldError
                            id={`${id}-title-error`}
                            errors={field.state.meta.errors}
                          />
                        )}
                      </Field>
                    );
                  }}
                </form.Field>
                <form.Field name="description">
                  {(field) => {
                    const invalid =
                      field.state.meta.isTouched && !field.state.meta.isValid;
                    return (
                      <Field data-invalid={invalid} data-disabled={pending}>
                        <FieldLabel htmlFor={`${id}-description`}>
                          {labels.description}
                        </FieldLabel>
                        <Textarea
                          id={`${id}-description`}
                          name={field.name}
                          value={field.state.value}
                          rows={5}
                          disabled={pending}
                          onBlur={field.handleBlur}
                          onChange={(event) =>
                            field.handleChange(event.target.value)
                          }
                          aria-invalid={invalid}
                          aria-describedby={`${id}-description-hint${invalid ? ` ${id}-description-error` : ""}`}
                        />
                        <FieldDescription id={`${id}-description-hint`}>
                          {labels.descriptionHint}
                        </FieldDescription>
                        {invalid && (
                          <FieldError
                            id={`${id}-description-error`}
                            errors={field.state.meta.errors}
                          />
                        )}
                      </Field>
                    );
                  }}
                </form.Field>
                <FormFeedback feedback={submission.feedback} labels={labels} />
              </FieldGroup>
            )}
          </form.Subscribe>
        </form>
      </CardContent>
      <CardFooter>
        <form.Subscribe
          selector={(state) => [state.canSubmit, state.isSubmitting] as const}
        >
          {([canSubmit, pending]) => (
            <Field orientation="horizontal">
              <Button
                type="button"
                variant="outline"
                disabled={pending}
                onClick={() => {
                  form.reset();
                  submission.reset();
                }}
              >
                {labels.reset}
              </Button>
              <Button type="submit" form={id} disabled={!canSubmit || pending}>
                {pending && <Loader size="sm" label={labels.submitting} />}
                {labels.submit}
              </Button>
            </Field>
          )}
        </form.Subscribe>
      </CardFooter>
    </Card>
  );
}

/** Combines text, email, select, and checkbox fields using TanStack Form. */
export function ProfileForm({
  initialValues,
  onSubmit,
  labels: overrides,
  className,
}: FormBlockProps<ProfileValues, ProfileFormLabels>) {
  const labels = { ...defaultProfileFormLabels, ...overrides };
  const id = useId();
  const roles = [
    { value: "designer", label: labels.designerRole },
    { value: "developer", label: labels.developerRole },
    { value: "manager", label: labels.managerRole },
  ];
  const schema = z.object({
    name: z
      .string()
      .trim()
      .min(2, labels.nameMinLength)
      .max(50, labels.nameMaxLength),
    email: z.email(labels.invalidEmail),
    role: z.enum(["designer", "developer", "manager"], {
      error: labels.invalidRole,
    }),
    notifications: z.boolean(),
  });
  const submission = useSubmission(onSubmit, labels.submitError);
  const form = useForm({
    defaultValues: {
      name: "",
      email: "",
      role: "",
      notifications: true,
      ...initialValues,
    },
    validators: { onBlur: schema, onSubmit: schema },
    onSubmit: async ({ value }) => submission.submit(schema.parse(value)),
  });
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>{labels.formTitle}</CardTitle>
        <CardDescription>{labels.formDescription}</CardDescription>
      </CardHeader>
      <CardContent>
        <form
          id={id}
          noValidate
          onSubmit={(event) => {
            event.preventDefault();
            void form.handleSubmit();
          }}
        >
          <form.Subscribe selector={(state) => state.isSubmitting}>
            {(pending) => (
              <FieldGroup>
                {(["name", "email"] as const).map((name) => (
                  <form.Field key={name} name={name}>
                    {(field) => {
                      const invalid =
                        field.state.meta.isTouched && !field.state.meta.isValid;
                      return (
                        <Field data-invalid={invalid} data-disabled={pending}>
                          <FieldLabel htmlFor={`${id}-${name}`}>
                            {labels[name]}
                          </FieldLabel>
                          <Input
                            id={`${id}-${name}`}
                            name={field.name}
                            type={name === "email" ? "email" : "text"}
                            autoComplete={name}
                            value={field.state.value}
                            disabled={pending}
                            onBlur={field.handleBlur}
                            onChange={(event) =>
                              field.handleChange(event.target.value)
                            }
                            aria-invalid={invalid}
                            aria-describedby={
                              invalid ? `${id}-${name}-error` : undefined
                            }
                          />
                          {invalid && (
                            <FieldError
                              id={`${id}-${name}-error`}
                              errors={field.state.meta.errors}
                            />
                          )}
                        </Field>
                      );
                    }}
                  </form.Field>
                ))}
                <form.Field name="role">
                  {(field) => {
                    const invalid =
                      field.state.meta.isTouched && !field.state.meta.isValid;
                    return (
                      <Field data-invalid={invalid} data-disabled={pending}>
                        <FieldLabel htmlFor={`${id}-role`}>
                          {labels.role}
                        </FieldLabel>
                        <Select
                          items={roles}
                          name={field.name}
                          value={field.state.value || null}
                          disabled={pending}
                          onValueChange={(value) =>
                            field.handleChange(value ?? "")
                          }
                        >
                          <SelectTrigger
                            id={`${id}-role`}
                            onBlur={field.handleBlur}
                            aria-invalid={invalid}
                            aria-describedby={
                              invalid ? `${id}-role-error` : undefined
                            }
                          >
                            <SelectValue placeholder={labels.rolePlaceholder} />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectList>
                              <SelectGroup>
                                {roles.map((role) => (
                                  <SelectItem
                                    key={role.value}
                                    value={role.value}
                                  >
                                    {role.label}
                                  </SelectItem>
                                ))}
                              </SelectGroup>
                            </SelectList>
                          </SelectContent>
                        </Select>
                        {invalid && (
                          <FieldError
                            id={`${id}-role-error`}
                            errors={field.state.meta.errors}
                          />
                        )}
                      </Field>
                    );
                  }}
                </form.Field>
                <form.Field name="notifications">
                  {(field) => (
                    <Field orientation="horizontal" data-disabled={pending}>
                      <Checkbox
                        id={`${id}-notifications`}
                        name={field.name}
                        checked={field.state.value}
                        disabled={pending}
                        onBlur={field.handleBlur}
                        onCheckedChange={field.handleChange}
                      />
                      <FieldLabel htmlFor={`${id}-notifications`}>
                        {labels.notifications}
                      </FieldLabel>
                    </Field>
                  )}
                </form.Field>
                <FormFeedback feedback={submission.feedback} labels={labels} />
              </FieldGroup>
            )}
          </form.Subscribe>
        </form>
      </CardContent>
      <CardFooter>
        <form.Subscribe
          selector={(state) => [state.canSubmit, state.isSubmitting] as const}
        >
          {([canSubmit, pending]) => (
            <Field orientation="horizontal">
              <Button
                type="button"
                variant="outline"
                disabled={pending}
                onClick={() => {
                  form.reset();
                  submission.reset();
                }}
              >
                {labels.reset}
              </Button>
              <Button type="submit" form={id} disabled={!canSubmit || pending}>
                {pending && <Loader size="sm" label={labels.submitting} />}
                {labels.submit}
              </Button>
            </Field>
          )}
        </form.Subscribe>
      </CardFooter>
    </Card>
  );
}

"use client";

import * as React from "react";
import { Area, AreaChart as RechartsAreaChart } from "recharts";
import { cartesianAxes } from "@/components/charts/shared/axes";
import { defaultValueFormatter } from "@/components/charts/shared/format";
import { ChartFrame } from "@/components/charts/shared/frame";
import {
  seriesColor,
  seriesKeys,
  useChartAnimation,
  useSeriesVisibility,
} from "@/components/charts/shared/series";
import { chartTooltip } from "@/components/charts/shared/tooltip";
import type { CartesianChartProps, ChartCurve } from "@/components/charts/shared/types";

export { numberFormatter } from "@/components/charts/shared/format";
export {
  type ChartLabels,
  chartLabels,
  chartLabelsZhCN,
} from "@/components/charts/shared/labels";

export type AreaChartProps = CartesianChartProps & {
  readonly stacked?: boolean;
  readonly curve?: ChartCurve;
  /** Fades each area toward the axis. */
  readonly gradient?: boolean;
};

function AreaChart({
  data,
  config,
  index,
  categories,
  valueFormatter = defaultValueFormatter,
  showLegend = false,
  showTooltip = true,
  showGrid,
  showXAxis,
  showYAxis = false,
  dir,
  stacked = false,
  curve = "natural",
  gradient = false,
  loading,
  labels,
  className,
  children,
  "aria-label": ariaLabel,
}: AreaChartProps) {
  const series = seriesKeys(config, categories);
  const { hidden, toggle } = useSeriesVisibility();
  const animate = useChartAnimation();
  const id = React.useId().replace(/:/g, "");
  return (
    <ChartFrame
      data={data}
      config={config}
      index={index}
      series={series}
      valueFormatter={valueFormatter}
      loading={loading}
      labels={labels}
      legend={showLegend}
      hidden={hidden}
      onToggle={toggle}
      className={className}
      aria-label={ariaLabel}
    >
      <RechartsAreaChart
        data={[...data]}
        accessibilityLayer={false}
        margin={{ left: 12, right: 12 }}
      >
        {gradient ? (
          <defs>
            {series.map((key, position) => (
              <linearGradient
                key={key}
                id={`${id}-${position}`}
                x1="0"
                y1="0"
                x2="0"
                y2="1"
              >
                <stop
                  offset="5%"
                  stopColor={seriesColor(key, position)}
                  stopOpacity={0.8}
                />
                <stop
                  offset="95%"
                  stopColor={seriesColor(key, position)}
                  stopOpacity={0.1}
                />
              </linearGradient>
            ))}
          </defs>
        ) : null}
        {cartesianAxes({
          index,
          showGrid,
          showXAxis,
          showYAxis,
          dir,
          valueFormatter,
        })}
        {showTooltip
          ? chartTooltip({ valueFormatter, series, config, indicator: "dot" })
          : null}
        {series.map((key, position) => (
          <Area
            key={key}
            dataKey={key}
            type={curve}
            hide={hidden.has(key)}
            stackId={stacked ? "stack" : undefined}
            stroke={seriesColor(key, position)}
            fill={
              gradient ? `url(#${id}-${position})` : seriesColor(key, position)
            }
            fillOpacity={gradient ? 1 : 0.4}
            isAnimationActive={animate}
          />
        ))}
        {children}
      </RechartsAreaChart>
    </ChartFrame>
  );
}

export { AreaChart };

"use client";

import { Bar, Cell, BarChart as RechartsBarChart } from "recharts";
import { cartesianAxes } from "@/components/charts/shared/axes";
import { defaultValueFormatter } from "@/components/charts/shared/format";
import { ChartFrame } from "@/components/charts/shared/frame";
import {
  seriesColor,
  seriesKeys,
  useChartAnimation,
  useSeriesVisibility,
} from "@/components/charts/shared/series";
import { chartTooltip } from "@/components/charts/shared/tooltip";
import type { CartesianChartProps } from "@/components/charts/shared/types";

export { numberFormatter } from "@/components/charts/shared/format";
export {
  type ChartLabels,
  chartLabels,
  chartLabelsZhCN,
} from "@/components/charts/shared/labels";

export type BarChartProps = CartesianChartProps & {
  /** `horizontal` lays bars along the x axis with categories on the y axis. */
  readonly layout?: "vertical" | "horizontal";
  readonly stacked?: boolean;
  readonly radius?: number;
  /** Colors negative values; defaults to the destructive color. */
  readonly negativeColor?: string;
};

function barRadius(
  radius: number,
  horizontal: boolean,
): [number, number, number, number] {
  if (horizontal) return [0, radius, radius, 0];
  return [radius, radius, 0, 0];
}

function BarChart({
  data,
  config,
  index,
  categories,
  valueFormatter = defaultValueFormatter,
  showLegend = false,
  showTooltip = true,
  showGrid,
  showXAxis,
  showYAxis,
  dir,
  layout = "vertical",
  stacked = false,
  radius = 8,
  negativeColor = "var(--destructive)",
  loading,
  labels,
  className,
  children,
  "aria-label": ariaLabel,
}: BarChartProps) {
  const series = seriesKeys(config, categories);
  const { hidden, toggle } = useSeriesVisibility();
  const animate = useChartAnimation();
  const horizontal = layout === "horizontal";
  const visible = series.filter((key) => !hidden.has(key));
  const last = visible.at(-1);
  return (
    <ChartFrame
      data={data}
      config={config}
      index={index}
      series={series}
      valueFormatter={valueFormatter}
      loading={loading}
      labels={labels}
      legend={showLegend}
      hidden={hidden}
      onToggle={toggle}
      className={className}
      aria-label={ariaLabel}
    >
      <RechartsBarChart
        data={[...data]}
        layout={horizontal ? "vertical" : "horizontal"}
        accessibilityLayer={false}
        margin={{ left: 12, right: 12 }}
      >
        {cartesianAxes({
          index,
          showGrid,
          showXAxis: showXAxis ?? !horizontal,
          showYAxis: showYAxis ?? horizontal,
          dir,
          vertical: horizontal,
          valueFormatter,
        })}
        {showTooltip
          ? chartTooltip({
              valueFormatter,
              series,
              config,
              indicator: "dashed",
            })
          : null}
        {series.map((key, position) => {
          const color = seriesColor(key, position);
          // Stacked bars round only the outer end of the stack.
          const rounded = !stacked || key === last;
          return (
            <Bar
              key={key}
              dataKey={key}
              hide={hidden.has(key)}
              stackId={stacked ? "stack" : undefined}
              fill={color}
              radius={rounded ? barRadius(radius, horizontal) : 0}
              isAnimationActive={animate}
            >
              {data.map((row, rowIndex) => {
                const value = row[key];
                const negative = typeof value === "number" && value < 0;
                return (
                  <Cell
                    // biome-ignore lint/suspicious/noArrayIndexKey: one cell per positional row.
                    key={rowIndex}
                    fill={negative ? negativeColor : color}
                  />
                );
              })}
            </Bar>
          );
        })}
        {children}
      </RechartsBarChart>
    </ChartFrame>
  );
}

export { BarChart };

"use client";

import { cn } from "cn";
import * as React from "react";
import type { TooltipValueType } from "recharts";
import * as RechartsPrimitive from "recharts";

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const;

const INITIAL_DIMENSION = { width: 320, height: 200 } as const;
type TooltipNameType = number | string;

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode;
    icon?: React.ComponentType;
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>;

/**
 * Escapes a series key for a CSS custom property name. Letters, digits, `_`,
 * `-` and non-ASCII characters such as Chinese stay as they are; anything
 * else becomes a CSS escape, so distinct keys never share a variable.
 */
function chartKey(key: string) {
  return key.replace(
    /[^\w\u0080-￿-]/g,
    (char) => `\\${char.charCodeAt(0).toString(16)} `,
  );
}

type ChartContextProps = {
  config: ChartConfig;
};

const ChartContext = React.createContext<ChartContextProps | null>(null);

function useChart() {
  const context = React.useContext(ChartContext);

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />");
  }

  return context;
}

function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig;
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"];
  initialDimension?: {
    width: number;
    height: number;
  };
}) {
  const uniqueId = React.useId();
  const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`;

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-video justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-hidden [&_.recharts-surface]:outline-hidden",
          className,
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme ?? config.color,
  );

  if (!colorConfig.length) {
    return null;
  }

  return (
    <style>
      {Object.entries(THEMES)
        .map(
          ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ??
      itemConfig.color;
    return color ? `  --color-${chartKey(key)}: ${color};` : null;
  })
  .join("\n")}
}
`,
        )
        .join("\n")}
    </style>
  );
};

const ChartTooltip = RechartsPrimitive.Tooltip;

// Recharts passes configuration alongside DOM attributes to custom content.
const chartOnlyProps = new Set([
  "accessibilityLayer",
  "activeIndex",
  "coordinate",
  "viewBox",
  "separator",
  "wrapperClassName",
  "contentStyle",
  "itemStyle",
  "labelStyle",
  "itemSorter",
  "allowEscapeViewBox",
  "animationDuration",
  "animationEasing",
  "axisId",
  "content",
  "cursor",
  "defaultIndex",
  "filterNull",
  "includeHidden",
  "isAnimationActive",
  "offset",
  "payloadUniqBy",
  "portal",
  "position",
  "reverseDirection",
  "shared",
  "trigger",
  "useTranslate3d",
  "wrapperStyle",
  "iconSize",
  "iconType",
  "layout",
  "align",
  "inactiveColor",
  "formatter",
  "chartWidth",
  "chartHeight",
  "width",
  "height",
  "margin",
  "onBBoxUpdate",
]);
function chartDomProps(props: object): React.ComponentProps<"div"> {
  return Object.fromEntries(
    Object.entries(props).filter(([key]) => !chartOnlyProps.has(key)),
  );
}

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
  ...props
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean;
    hideIndicator?: boolean;
    indicator?: "line" | "dot" | "dashed";
    nameKey?: string;
    labelKey?: string;
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart();

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null;
    }

    const [item] = payload;
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
    const itemConfig = getPayloadConfigFromPayload(config, item, key);
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : itemConfig?.label;

    if (labelFormatter) {
      return (
        <div className={cn("font-medium", labelClassName)}>
          {labelFormatter(value, payload)}
        </div>
      );
    }

    if (!value) {
      return null;
    }

    return <div className={cn("font-medium", labelClassName)}>{value}</div>;
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ]);

  if (!active || !payload?.length) {
    return null;
  }

  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div
      {...chartDomProps(props)}
      className={cn(
        "grid min-w-32 items-start gap-1.5 rounded-xl bg-popover px-2.5 py-1.5 text-popover-foreground text-xs shadow-lg ring-1 ring-foreground/5 dark:ring-foreground/10",
        className,
      )}
    >
      {!nestLabel ? tooltipLabel : null}
      <div className="grid gap-1.5">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`;
            const itemConfig = getPayloadConfigFromPayload(config, item, key);
            const indicatorColor = color ?? item.payload?.fill ?? item.color;

            return (
              <div
                // biome-ignore lint/suspicious/noArrayIndexKey: Recharts payload entries are positional and can share a series dataKey.
                key={index}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center",
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-xs border-border bg-(--color-bg)",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            },
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center",
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label ?? item.name}
                        </span>
                      </div>
                      {item.value != null && (
                        <span className="font-medium font-mono text-foreground tabular-nums">
                          {typeof item.value === "number"
                            ? item.value.toLocaleString()
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            );
          })}
      </div>
    </div>
  );
}

const ChartLegend = RechartsPrimitive.Legend;

function ChartLegendContent({
  className,
  hideIcon = false,
  payload,
  verticalAlign = "bottom",
  nameKey,
  ...props
}: React.ComponentProps<"div"> & {
  hideIcon?: boolean;
  nameKey?: string;
} & RechartsPrimitive.DefaultLegendContentProps) {
  const { config } = useChart();

  if (!payload?.length) {
    return null;
  }

  return (
    <div
      {...chartDomProps(props)}
      className={cn(
        "flex items-center justify-center gap-4",
        verticalAlign === "top" ? "pb-3" : "pt-3",
        className,
      )}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item, index) => {
          const key = `${nameKey ?? item.dataKey ?? "value"}`;
          const itemConfig = getPayloadConfigFromPayload(config, item, key);

          return (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: Recharts legend entries are positional and can share a series dataKey.
              key={index}
              className={cn(
                "flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground",
              )}
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <div
                  className="h-2 w-2 shrink-0 rounded-xs"
                  style={{
                    backgroundColor: item.color,
                  }}
                />
              )}
              {itemConfig?.label}
            </div>
          );
        })}
    </div>
  );
}

function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string,
) {
  if (typeof payload !== "object" || payload === null) {
    return undefined;
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined;

  let configLabelKey: string = key;

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string;
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string;
  }

  return configLabelKey in config ? config[configLabelKey] : config[key];
}

export {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
  ChartTooltip,
  ChartTooltipContent,
  chartKey,
};

