import { useReducedMotion } from "motion/react";
import * as React from "react";
import { type ChartConfig, chartKey } from "@/components/charts/chart";

export function seriesKeys(
  config: ChartConfig,
  categories: readonly string[] | undefined,
) {
  return categories ?? Object.keys(config);
}

/** The series color, falling back to the theme palette when config has none. */
export function seriesColor(key: string, position: number) {
  return `var(--color-${chartKey(key)}, var(--chart-${(position % 5) + 1}))`;
}

export function toggleSeries(hidden: ReadonlySet<string>, key: string) {
  const next = new Set(hidden);
  if (!next.delete(key)) next.add(key);
  return next;
}

/** Tracks which series the legend has hidden. */
export function useSeriesVisibility() {
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(new Set());
  const toggle = React.useCallback((key: string) => {
    setHidden((current) => toggleSeries(current, key));
  }, []);
  return { hidden, toggle };
}

export function useChartAnimation() {
  return !useReducedMotion();
}

import { ChartTooltip, ChartTooltipContent } from "@/components/charts/chart";
import { formatValue, type ValueFormatter } from "@/components/charts/shared/format";
import { seriesColor } from "@/components/charts/shared/series";

/** The default tooltip, formatting values with the chart's formatter. */
export function chartTooltip({
  valueFormatter,
  series,
  config,
  indicator = "dot",
  hideLabel = false,
  nameKey,
}: {
  valueFormatter: ValueFormatter;
  series: readonly string[];
  config: Record<string, { label?: React.ReactNode }>;
  indicator?: "dot" | "line" | "dashed";
  hideLabel?: boolean;
  nameKey?: string;
}) {
  return (
    <ChartTooltip
      key="tooltip"
      content={
        <ChartTooltipContent
          indicator={indicator}
          hideLabel={hideLabel}
          nameKey={nameKey}
          formatter={(value, name, item) => {
            const key = String(nameKey ? item.payload?.[nameKey] : name);
            const position = Math.max(series.indexOf(key), 0);
            return (
              <div className="flex w-full items-center gap-2">
                <span
                  className="size-2.5 shrink-0 rounded-xs"
                  style={{
                    backgroundColor:
                      item.payload?.fill ??
                      item.color ??
                      seriesColor(key, position),
                  }}
                />
                <span className="flex-1 text-muted-foreground">
                  {config[key]?.label ?? key}
                </span>
                <span className="font-medium font-mono text-foreground tabular-nums">
                  {formatValue(value, valueFormatter)}
                </span>
              </div>
            );
          }}
        />
      }
    />
  );
}

