"use client";

import {
  type ComponentProps,
  createContext,
  type ReactNode,
  type RefObject,
  useCallback,
  useContext,
  useMemo,
  useReducer,
  useRef,
  useState,
} from "react";
import type { GlassProps } from "@/lib/glass/with-glass";
import type { ImageLabelOverrides } from "@/components/ui/image/labels";
import { ImagePreview } from "@/components/ui/image/preview";

interface GroupEntry {
  readonly src: string;
  readonly alt: string | undefined;
  readonly element: RefObject<HTMLElement | null>;
}

interface GroupContextValue {
  register(id: string, entry: GroupEntry): () => void;
  show(id: string): void;
}

const ImageGroupContext = createContext<GroupContextValue | null>(null);

export function useImageGroup() {
  return useContext(ImageGroupContext);
}

export interface ImageGroupPreviewConfig {
  readonly open?: boolean;
  readonly onOpenChange?: (open: boolean) => void;
  readonly index?: number;
  readonly onIndexChange?: (index: number) => void;
  readonly container?: ComponentProps<typeof ImagePreview>["container"];
}

export interface ImageGroupProps extends GlassProps {
  readonly children: ReactNode;
  readonly preview?: ImageGroupPreviewConfig;
  /** Alt text for previewed images without their own. */
  readonly alt?: string;
  readonly labels?: ImageLabelOverrides;
}

/** Document order, so the gallery matches what the reader sees. */
function byPosition(a: GroupEntry, b: GroupEntry) {
  const first = a.element.current;
  const second = b.element.current;
  if (!first || !second) return 0;
  const position = first.compareDocumentPosition(second);
  if (position & Node.DOCUMENT_POSITION_FOLLOWING) return -1;
  if (position & Node.DOCUMENT_POSITION_PRECEDING) return 1;
  return 0;
}

function sortedEntries(entries: Map<string, GroupEntry>) {
  return [...entries].sort(([, a], [, b]) => byPosition(a, b));
}

/**
 * Previews the Images inside it as one gallery that opens on the clicked
 * image. It renders no wrapper element.
 */
export function ImageGroup({
  children,
  preview = {},
  alt,
  labels,
  glass,
  frosted,
}: Readonly<ImageGroupProps>) {
  const entries = useRef(new Map<string, GroupEntry>());
  const [, refresh] = useReducer((count: number) => count + 1, 0);
  const [localOpen, setLocalOpen] = useState(false);
  const [localIndex, setLocalIndex] = useState(0);
  const open = preview.open ?? localOpen;
  const index = preview.index ?? localIndex;
  const { onOpenChange, onIndexChange } = preview;

  const setOpen = useCallback(
    (next: boolean) => {
      setLocalOpen(next);
      onOpenChange?.(next);
    },
    [onOpenChange],
  );
  const setIndex = useCallback(
    (next: number) => {
      setLocalIndex(next);
      onIndexChange?.(next);
    },
    [onIndexChange],
  );

  const context = useMemo<GroupContextValue>(
    () => ({
      register(id, entry) {
        entries.current.set(id, entry);
        refresh();
        return () => {
          entries.current.delete(id);
          refresh();
        };
      },
      show(id) {
        const list = sortedEntries(entries.current);
        setIndex(
          Math.max(
            0,
            list.findIndex(([key]) => key === id),
          ),
        );
        setOpen(true);
      },
    }),
    [setIndex, setOpen],
  );

  const items = sortedEntries(entries.current).map(([, entry]) => ({
    src: entry.src,
    alt: entry.alt,
  }));

  return (
    <ImageGroupContext.Provider value={context}>
      {children}
      {items.length > 0 && (
        <ImagePreview
          images={items}
          open={open}
          onOpenChange={setOpen}
          index={index}
          onIndexChange={setIndex}
          alt={alt}
          labels={labels}
          container={preview.container}
          glass={glass}
          frosted={frosted}
        />
      )}
    </ImageGroupContext.Provider>
  );
}

"use client";

import { cn } from "cn";
import { ImageOff } from "lucide-react";
import {
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import type { GlassProps } from "@/lib/glass/with-glass";
import { useImageGroup } from "@/components/ui/image/group";
import { type ImageLabelOverrides, imageLabels } from "@/components/ui/image/labels";
import { ImagePreview } from "@/components/ui/image/preview";

export interface ImagePreviewConfig {
  /** A larger image to preview instead of `src`. */
  readonly src?: string;
  readonly open?: boolean;
  readonly defaultOpen?: boolean;
  readonly onOpenChange?: (open: boolean) => void;
  readonly container?: ComponentProps<typeof ImagePreview>["container"];
}

export interface ImageProps
  extends Omit<ComponentProps<"img">, "src" | "alt" | "width" | "height">,
    GlassProps {
  readonly src: string;
  readonly alt: string;
  readonly width?: number | string;
  readonly height?: number | string;
  /** How the image fills its box. Defaults to `cover`. */
  readonly fit?: CSSProperties["objectFit"];
  /** Shown when the image fails to load. */
  readonly fallback?: ReactNode;
  /**
   * Opens a fullscreen preview on click. Inside ImageGroup, images take
   * part unless this is `false`.
   */
  readonly preview?: boolean | ImagePreviewConfig;
  readonly labels?: ImageLabelOverrides;
}

type LoadState = "loading" | "ready" | "error";

function previewConfig(preview: ImageProps["preview"]) {
  if (typeof preview === "object") return preview;
  return {};
}

function cssSize(size: number | string | undefined) {
  if (typeof size === "number") return `${size}px`;
  return size;
}

function DefaultFallback({ label }: Readonly<{ label: string }>) {
  return (
    <span className="flex size-full flex-col items-center justify-center gap-1 bg-muted p-2 text-center text-muted-foreground text-xs">
      <ImageOff aria-hidden="true" className="size-5" />
      {label}
    </span>
  );
}

export function Image({
  src,
  alt,
  width,
  height,
  fit = "cover",
  fallback,
  preview,
  labels,
  glass,
  frosted,
  className,
  style,
  onLoad,
  onError,
  ...props
}: Readonly<ImageProps>) {
  const text = { ...imageLabels, ...labels };
  const group = useImageGroup();
  const config = previewConfig(preview);
  const grouped = group !== null && preview !== false;
  const previewable = grouped || Boolean(preview);
  const previewSrc = config.src ?? src;

  const [load, setLoad] = useState<{ src: string; state: LoadState }>({
    src,
    state: "loading",
  });
  let state: LoadState = "loading";
  if (load.src === src) state = load.state;
  const imageRef = useRef<HTMLImageElement>(null);
  const boxRef = useRef<HTMLElement>(null);

  // A cached image can finish before hydration attaches onLoad.
  useEffect(() => {
    const image = imageRef.current;
    if (!image?.complete) return;
    setLoad({ src, state: image.naturalWidth > 0 ? "ready" : "error" });
  }, [src]);

  const id = useId();
  const register = group?.register;
  useEffect(() => {
    if (!grouped || !register) return;
    return register(id, { src: previewSrc, alt, element: boxRef });
  }, [grouped, register, id, previewSrc, alt]);

  const [localOpen, setLocalOpen] = useState(config.defaultOpen ?? false);
  const open = config.open ?? localOpen;
  const setOpen = (next: boolean) => {
    setLocalOpen(next);
    config.onOpenChange?.(next);
  };
  const show = () => {
    if (grouped) group?.show(id);
    else setOpen(true);
  };

  const content = (
    <>
      {state === "loading" && (
        <span
          aria-hidden="true"
          className="absolute inset-0 animate-pulse bg-muted motion-reduce:animate-none"
        />
      )}
      {state === "error" &&
        (fallback ?? <DefaultFallback label={text.error} />)}
      <img
        {...props}
        ref={imageRef}
        src={src}
        alt={alt}
        onLoad={(event) => {
          setLoad({ src, state: "ready" });
          onLoad?.(event);
        }}
        onError={(event) => {
          setLoad({ src, state: "error" });
          onError?.(event);
        }}
        className={cn(
          "size-full",
          state === "error" && "absolute size-px opacity-0",
        )}
        style={{ objectFit: fit }}
      />
    </>
  );
  const boxClass = cn(
    "relative inline-flex overflow-hidden align-middle",
    className,
  );
  const boxStyle = { width: cssSize(width), height: cssSize(height), ...style };

  if (!previewable)
    return (
      <span
        ref={(node) => {
          boxRef.current = node;
        }}
        data-slot="image"
        data-state={state}
        className={boxClass}
        style={boxStyle}
      >
        {content}
      </span>
    );

  return (
    <>
      <button
        ref={(node) => {
          boxRef.current = node;
        }}
        type="button"
        data-slot="image"
        data-state={state}
        aria-label={text.preview(alt)}
        onClick={show}
        className={cn(
          boxClass,
          "cursor-zoom-in p-0 outline-none focus-visible:ring-3 focus-visible:ring-ring/50",
        )}
        style={boxStyle}
      >
        {content}
      </button>
      {!grouped && (
        <ImagePreview
          images={{ src: previewSrc, alt }}
          open={open}
          onOpenChange={setOpen}
          labels={labels}
          container={config.container}
          glass={glass}
          frosted={frosted}
        />
      )}
    </>
  );
}

"use client";

import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { cn } from "cn";
import {
  ChevronLeft,
  ChevronRight,
  RotateCcw,
  RotateCcwSquare,
  RotateCw,
  X,
  ZoomIn,
  ZoomOut,
} from "lucide-react";
import { useReducedMotion } from "motion/react";
import {
  type ComponentProps,
  type PointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import type { GlassProps } from "@/lib/glass/with-glass";
import { Button } from "@/components/ui/button";
import { Dialog, DialogOverlay, DialogTitle } from "@/components/ui/dialog";
import { TooltipButton } from "@/components/ui/tooltip-button";
import { type ImageLabelOverrides, imageLabels } from "@/components/ui/image/labels";
import {
  clampImageScale,
  defaultImageTransform,
  normalizeImageIndex,
  wrapImageIndex,
} from "@/components/ui/image/transform";

export type ImagePreviewItem = string | { src: string; alt?: string };

export interface ImagePreviewProps extends GlassProps {
  images: ImagePreviewItem | ImagePreviewItem[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  index?: number;
  initialIndex?: number;
  onIndexChange?: (index: number) => void;
  /** Alt text for items without their own, numbered by position. */
  alt?: string;
  container?: ComponentProps<typeof DialogPrimitive.Portal>["container"];
  className?: string;
  labels?: ImageLabelOverrides;
}

function itemSrc(item: ImagePreviewItem) {
  return typeof item === "string" ? item : item.src;
}

/** The fullscreen viewer behind Image's preview, usable on its own. */
function ImagePreview({
  images,
  open,
  onOpenChange,
  index: controlledIndex,
  initialIndex = 0,
  onIndexChange,
  alt,
  container,
  className,
  glass,
  frosted,
  labels,
}: ImagePreviewProps) {
  // glass and frosted apply to the toolbar and navigation buttons.
  const material = { glass, frosted };
  const text = { ...imageLabels, ...labels };
  const items = Array.isArray(images) ? images : [images];
  const list = items.map(itemSrc);
  const [localIndex, setIndex] = useState(initialIndex);
  const index = normalizeImageIndex(controlledIndex ?? localIndex, list.length);
  const [transform, setTransform] = useState(defaultImageTransform);
  const [dragging, setDragging] = useState(false);
  const reducedMotion = useReducedMotion();
  const close = () => onOpenChange(false);
  const imageRef = useRef<HTMLImageElement>(null);
  const pointers = useRef(new Map<number, { x: number; y: number }>());
  const gesture = useRef<{
    x: number;
    y: number;
    tx: number;
    ty: number;
    distance: number;
    scale: number;
  } | null>(null);
  const [retry, setRetry] = useState(0);
  const key = `${index}\u0000${list[index]}\u0000${retry}`;
  const [load, setLoad] = useState<{
    key: string;
    state: "ready" | "error";
  } | null>(null);
  const state = load?.key === key ? load.state : "loading";
  const reset = useCallback(() => {
    setTransform(defaultImageTransform);
    pointers.current.clear();
    gesture.current = null;
    setDragging(false);
  }, []);
  const select = useCallback(
    (next: number) => {
      if (!list.length) return;
      const value = wrapImageIndex(next, list.length);
      if (controlledIndex === undefined) setIndex(value);
      onIndexChange?.(value);
      reset();
    },
    [controlledIndex, list.length, onIndexChange, reset],
  );
  function zoomBy(delta: number) {
    setTransform((previous) => ({
      ...previous,
      scale: clampImageScale(previous.scale + delta),
    }));
  }
  function rotateBy(delta: number) {
    setTransform((previous) => ({
      ...previous,
      rotate: previous.rotate + delta,
    }));
  }
  useEffect(() => {
    if (open && controlledIndex === undefined) setIndex(initialIndex);
    reset();
  }, [open, controlledIndex, initialIndex, reset]);
  useEffect(() => {
    void key;
    reset();
  }, [key, reset]);
  useEffect(() => {
    if (!open) return;
    const image = imageRef.current;
    if (image?.complete)
      setLoad({ key, state: image.naturalWidth > 0 ? "ready" : "error" });
  }, [open, key]);
  function beginGesture() {
    const values = [...pointers.current.values()];
    if (!values.length) {
      gesture.current = null;
      setDragging(false);
      return;
    }
    const a = values[0];
    const b = values[1];
    gesture.current = {
      x: b ? (a.x + b.x) / 2 : a.x,
      y: b ? (a.y + b.y) / 2 : a.y,
      tx: transform.x,
      ty: transform.y,
      distance: b ? Math.hypot(a.x - b.x, a.y - b.y) : 0,
      scale: transform.scale,
    };
    setDragging(true);
  }
  const wheelRef = useCallback((node: HTMLDivElement | null) => {
    if (!node) return;
    const onWheel = (event: WheelEvent) => {
      event.preventDefault();
      // Zoom follows the wheel distance: trackpads glide in small steps, and
      // a mouse notch (about 100px) still zooms by roughly a quarter.
      const unit = [1, 16, window.innerHeight][event.deltaMode] ?? 1;
      const factor = Math.exp((-event.deltaY * unit) / 400);
      setTransform((previous) => ({
        ...previous,
        scale: clampImageScale(previous.scale * factor),
      }));
    };
    node.addEventListener("wheel", onWheel, { passive: false });
    return () => node.removeEventListener("wheel", onWheel);
  }, []);
  function onPointerDown(event: PointerEvent<HTMLDivElement>) {
    if (
      event.button !== 0 ||
      state !== "ready" ||
      (event.target instanceof Element && event.target.closest("button"))
    )
      return;
    event.currentTarget.setPointerCapture?.(event.pointerId);
    pointers.current.set(event.pointerId, {
      x: event.clientX,
      y: event.clientY,
    });
    beginGesture();
  }
  function onPointerMove(event: PointerEvent<HTMLDivElement>) {
    if (!pointers.current.has(event.pointerId) || !gesture.current) return;
    pointers.current.set(event.pointerId, {
      x: event.clientX,
      y: event.clientY,
    });
    const [a, b] = [...pointers.current.values()];
    const start = gesture.current;
    setTransform((previous) => ({
      ...previous,
      x: start.tx + (b ? (a.x + b.x) / 2 : a.x) - start.x,
      y: start.ty + (b ? (a.y + b.y) / 2 : a.y) - start.y,
      scale:
        b && start.distance > 0
          ? clampImageScale(
              (start.scale * Math.hypot(a.x - b.x, a.y - b.y)) / start.distance,
            )
          : previous.scale,
    }));
  }
  function onPointerEnd(event: PointerEvent<HTMLDivElement>) {
    pointers.current.delete(event.pointerId);
    beginGesture();
  }
  if (!list.length) return null;
  const resolvedAlt = alt ?? text.defaultAlt;
  const altAt = (position: number) => {
    const item = items[position];
    if (typeof item === "object" && item.alt) return item.alt;
    return text.imageAlt(resolvedAlt, position + 1);
  };
  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) close();
      }}
    >
      <DialogPrimitive.Portal container={container}>
        <DialogOverlay />
        <DialogPrimitive.Popup
          data-slot="image-preview"
          aria-describedby={undefined}
          className={cn(
            "fixed inset-0 z-50 flex h-dvh w-screen flex-col bg-background text-foreground text-sm outline-none",
            className,
          )}
          onKeyDown={(event) => {
            if (
              event.target instanceof Element &&
              event.target.closest(
                "input,textarea,select,[contenteditable=true]",
              )
            )
              return;
            if (event.key === "ArrowLeft") {
              event.preventDefault();
              select(index - 1);
            } else if (event.key === "ArrowRight") {
              event.preventDefault();
              select(index + 1);
            } else if (event.key === "+" || event.key === "=") {
              event.preventDefault();
              zoomBy(0.25);
            } else if (event.key === "-") {
              event.preventDefault();
              zoomBy(-0.25);
            } else if (event.key === "0") {
              event.preventDefault();
              reset();
            }
          }}
        >
          <DialogTitle className="sr-only">{text.viewer}</DialogTitle>
          <div className="flex shrink-0 flex-wrap items-center gap-1 px-3 py-2">
            <TooltipButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.zoomOut}
              onClick={() => zoomBy(-0.25)}
            >
              <ZoomOut aria-hidden="true" />
            </TooltipButton>
            <span className="min-w-12 text-center tabular-nums">
              {Math.round(transform.scale * 100)}%
            </span>
            <TooltipButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.zoomIn}
              onClick={() => zoomBy(0.25)}
            >
              <ZoomIn aria-hidden="true" />
            </TooltipButton>
            <TooltipButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.rotateCounterclockwise}
              onClick={() => rotateBy(-90)}
            >
              <RotateCcw aria-hidden="true" />
            </TooltipButton>
            <TooltipButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.rotateClockwise}
              onClick={() => rotateBy(90)}
            >
              <RotateCw aria-hidden="true" />
            </TooltipButton>
            <TooltipButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.reset}
              disabled={
                transform.scale === 1 &&
                transform.rotate === 0 &&
                transform.x === 0 &&
                transform.y === 0
              }
              onClick={reset}
            >
              <RotateCcwSquare aria-hidden="true" />
            </TooltipButton>
            <span className="ms-auto text-muted-foreground tabular-nums">
              {index + 1} / {list.length}
            </span>
            <TooltipButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.close}
              onClick={close}
            >
              <X aria-hidden="true" />
            </TooltipButton>
          </div>
          <span role="status" className="sr-only">
            {text.position(index + 1, list.length)}
          </span>
          <div
            ref={wheelRef}
            role="none"
            className={cn(
              "relative flex min-h-0 flex-1 touch-none items-center justify-center overflow-hidden",
              dragging ? "cursor-grabbing" : "cursor-grab",
            )}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerEnd}
            onPointerCancel={onPointerEnd}
            onLostPointerCapture={onPointerEnd}
          >
            {state === "loading" && <span role="status">{text.loading}</span>}
            {state === "error" && (
              <div className="flex flex-col items-center gap-3">
                <span role="alert" className="text-destructive">
                  {text.error}
                </span>
                <Button
                  variant="outline"
                  onClick={() => {
                    setLoad(null);
                    setRetry((previous) => previous + 1);
                  }}
                >
                  {text.retry}
                </Button>
              </div>
            )}
            <img
              ref={imageRef}
              key={key}
              src={list[index]}
              alt={altAt(index)}
              draggable={false}
              onLoad={() => setLoad({ key, state: "ready" })}
              onError={() => setLoad({ key, state: "error" })}
              className={cn(
                "max-h-full max-w-full select-none object-contain",
                state !== "ready" && "absolute opacity-0",
              )}
              style={{
                transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale}) rotate(${transform.rotate}deg)`,
                transition:
                  dragging || reducedMotion ? "none" : "transform 150ms ease",
              }}
            />
            {list.length > 1 && (
              <>
                <Button
                  {...material}
                  variant="ghost"
                  size="icon"
                  className="absolute inset-s-3 z-10 bg-background/80"
                  onClick={() => select(index - 1)}
                  aria-label={text.previous}
                >
                  <ChevronLeft aria-hidden="true" />
                </Button>
                <Button
                  {...material}
                  variant="ghost"
                  size="icon"
                  className="absolute inset-e-3 z-10 bg-background/80"
                  onClick={() => select(index + 1)}
                  aria-label={text.next}
                >
                  <ChevronRight aria-hidden="true" />
                </Button>
              </>
            )}
          </div>
          {list.length > 1 && (
            <div
              data-slot="image-preview-thumbnails"
              className="shrink-0 overflow-x-auto px-3 py-2"
            >
              <div className="mx-auto flex w-max gap-2">
                {list.map((src, imageIndex) => (
                  <Button
                    // biome-ignore lint/suspicious/noArrayIndexKey: Repeated URLs are distinct numbered gallery entries.
                    key={`${src}-${imageIndex}`}
                    variant="ghost"
                    size="icon"
                    className={cn(
                      "size-12 shrink-0 overflow-hidden rounded-lg p-0 ring-2 ring-transparent",
                      imageIndex === index
                        ? "ring-primary"
                        : "opacity-50 hover:opacity-80",
                    )}
                    aria-pressed={imageIndex === index}
                    aria-label={text.open(resolvedAlt, imageIndex + 1)}
                    onClick={() => select(imageIndex)}
                  >
                    <img
                      src={src}
                      alt={text.thumbnail(resolvedAlt, imageIndex + 1)}
                      className="size-full object-cover"
                    />
                  </Button>
                ))}
              </div>
            </div>
          )}
        </DialogPrimitive.Popup>
      </DialogPrimitive.Portal>
    </Dialog>
  );
}

export { ImagePreview };

export type ImageTransform = {
  scale: number;
  rotate: number;
  x: number;
  y: number;
};
export const defaultImageTransform: ImageTransform = {
  scale: 1,
  rotate: 0,
  x: 0,
  y: 0,
};
export function clampImageScale(scale: number) {
  return Number.isFinite(scale) ? Math.min(5, Math.max(0.1, scale)) : 1;
}
export function normalizeImageIndex(index: number, length: number) {
  if (length > 0)
    return Math.min(
      length - 1,
      Math.max(0, Number.isFinite(index) ? Math.trunc(index) : 0),
    );
  return 0;
}
export function wrapImageIndex(index: number, length: number) {
  return length > 0 ? ((Math.trunc(index) % length) + length) % length : 0;
}

