"use client";

import { Progress as ProgressPrimitive } from "@base-ui/react/progress";
import { cn } from "cn";
import { useEffect, useState } from "react";

export interface NavigationProgressProps {
  active: boolean;
  delay?: number;
  finishDelay?: number;
  label?: string;
  position?: "fixed" | "absolute";
  className?: string;
}

/** Router-independent navigation feedback with delayed start and completion. */
export function NavigationProgress({
  active,
  delay = 120,
  finishDelay = 180,
  label = "Loading page",
  position = "fixed",
  className,
}: NavigationProgressProps) {
  const [progress, setProgress] = useState(0);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    let interval: ReturnType<typeof setInterval> | undefined;
    let timer: ReturnType<typeof setTimeout>;
    if (active) {
      setProgress((value) => (value === 100 ? 12 : value));
      timer = setTimeout(
        () => {
          setProgress(12);
          setVisible(true);
          interval = setInterval(
            () =>
              setProgress((value) => Math.min(90, value + (90 - value) * 0.12)),
            250,
          );
        },
        Math.max(0, delay),
      );
    } else {
      setProgress(100);
      timer = setTimeout(
        () => {
          setVisible(false);
          setProgress(0);
        },
        Math.max(0, finishDelay),
      );
    }
    return () => {
      clearTimeout(timer);
      clearInterval(interval);
    };
  }, [active, delay, finishDelay]);
  let state = "idle";
  if (visible) state = active ? "loading" : "complete";
  return (
    <ProgressPrimitive.Root
      value={active ? null : 100}
      aria-label={label}
      hidden={!visible}
      data-slot="navigation-progress"
      data-state={state}
      className={cn(
        "pointer-events-none inset-x-0 top-0 z-50",
        position === "fixed" ? "fixed" : "absolute",
        className,
      )}
    >
      <ProgressPrimitive.Track
        data-slot="navigation-progress-track"
        className="h-0.5 w-full overflow-hidden"
      >
        <div
          aria-hidden="true"
          data-slot="navigation-progress-indicator"
          className="h-full origin-left bg-primary transition-[transform] duration-200 ease-out motion-reduce:transition-none rtl:origin-right"
          style={{ transform: `scaleX(${progress / 100})` }}
        />
      </ProgressPrimitive.Track>
    </ProgressPrimitive.Root>
  );
}

"use client";

import { Button, buttonVariants } from "@/components/ui/button";
import { ButtonGroup } from "@/components/ui/button-group";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectList,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import type { VariantProps } from "class-variance-authority";
import { cn } from "cn";
import {
  ChevronFirstIcon,
  ChevronLastIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  MoreHorizontalIcon,
} from "lucide-react";
import * as React from "react";
import { type GlassProps, withGlass } from "@/lib/glass/with-glass";

// Keep grouped buttons, page input, and selects on the same opaque surface.
const paginationControlClassName =
  "border-border bg-background text-foreground hover:bg-muted disabled:bg-background disabled:text-muted-foreground disabled:opacity-100 dark:bg-background dark:hover:bg-muted";

interface PaginationRangeInfo {
  page: number;
  perPage: number;
  totalCount?: number;
  pageCount?: number;
  from: number;
  to: number;
}

interface PaginationLabels {
  navigation?: string;
  firstPage?: string;
  previousPage?: string;
  nextPage?: string;
  lastPage?: string;
  pageNumber?: string;
  pageSize?: string;
  range?: (info: PaginationRangeInfo) => React.ReactNode;
}

type PaginationControlsMode = "full" | "simple";
type PaginationProps = React.ComponentProps<"nav"> & {
  page?: number;
  onPageChange?: (page: number) => void;
  perPage?: number;
  totalCount?: number;
  hasNextPage?: boolean;
  controls?: PaginationControlsMode;
  disabled?: boolean;
  labels?: PaginationLabels;
};

type PaginationContextValue = PaginationRangeInfo & {
  disabled: boolean;
  controls: PaginationControlsMode;
  canPrevious: boolean;
  canNext: boolean;
  changePage: (page: number) => void;
  labels: Required<PaginationLabels>;
};

const defaultLabels: Required<PaginationLabels> = {
  navigation: "Pagination",
  firstPage: "First page",
  previousPage: "Previous page",
  nextPage: "Next page",
  lastPage: "Last page",
  pageNumber: "Page number",
  pageSize: "Page size",
  range: ({ from, to, totalCount, page }) =>
    totalCount === undefined
      ? `Page ${page}`
      : `Showing ${from}–${to} of ${totalCount}`,
};
const PaginationContext = React.createContext<PaginationContextValue | null>(
  null,
);

function usePagination() {
  const context = React.useContext(PaginationContext);
  if (!context)
    throw new Error("Pagination parts require a Pagination parent.");
  return context;
}

function safeInteger(value: number, fallback: number, minimum: number): number {
  return Number.isFinite(value)
    ? Math.min(Math.max(Math.floor(value), minimum), Number.MAX_SAFE_INTEGER)
    : fallback;
}

function pageRange(
  page: number,
  perPage: number,
  totalCount?: number,
): PaginationRangeInfo {
  const size = safeInteger(perPage, 10, 1);
  const total =
    totalCount === undefined ? undefined : safeInteger(totalCount, 0, 0);
  const pageCount =
    total === undefined ? undefined : Math.max(1, Math.ceil(total / size));
  const current = Math.min(
    safeInteger(page, 1, 1),
    pageCount ?? Number.MAX_SAFE_INTEGER,
  );
  return {
    page: current,
    perPage: size,
    totalCount: total,
    pageCount,
    from:
      total === 0
        ? 0
        : Math.min((current - 1) * size + 1, Number.MAX_SAFE_INTEGER),
    to:
      total === 0
        ? 0
        : Math.min(current * size, total ?? Number.MAX_SAFE_INTEGER),
  };
}

function Pagination({
  className,
  page: controlledPage,
  onPageChange,
  perPage = 10,
  totalCount,
  hasNextPage,
  controls = "full",
  disabled = false,
  labels: labelsProp,
  children,
  ...props
}: PaginationProps) {
  const [internalPage, setInternalPage] = React.useState(1);
  const requestedPage = controlledPage ?? internalPage;
  const info = pageRange(requestedPage, perPage, totalCount);
  const labels = {
    ...defaultLabels,
    ...Object.fromEntries(
      Object.entries(labelsProp ?? {}).filter(
        ([, value]) => value !== undefined,
      ),
    ),
  };
  const correction = React.useRef<string | null>(null);
  React.useEffect(() => {
    if (requestedPage === info.page) {
      correction.current = null;
      return;
    }
    const key = `${requestedPage}:${info.page}:${info.perPage}:${info.totalCount}`;
    if (correction.current === key) return;
    correction.current = key;
    if (controlledPage === undefined) setInternalPage(info.page);
    onPageChange?.(info.page);
  }, [
    requestedPage,
    info.page,
    info.perPage,
    info.totalCount,
    controlledPage,
    onPageChange,
  ]);

  const empty = info.totalCount === 0;
  const canPrevious = !disabled && !empty && info.page > 1;
  const canNext =
    !disabled &&
    !empty &&
    (info.pageCount === undefined
      ? hasNextPage === true && info.page < Number.MAX_SAFE_INTEGER
      : info.page < info.pageCount);
  const context: PaginationContextValue = {
    ...info,
    disabled,
    controls,
    canPrevious,
    canNext,
    labels,
    changePage: (next) => {
      if (disabled || empty || !Number.isFinite(next)) return;
      const target = pageRange(next, info.perPage, info.totalCount).page;
      if (target === info.page) return;
      if (
        info.pageCount === undefined &&
        ((target !== info.page - 1 && target !== info.page + 1) ||
          (target > info.page && !canNext))
      )
        return;
      if (controlledPage === undefined) setInternalPage(target);
      onPageChange?.(target);
    },
  };
  return (
    <PaginationContext.Provider value={context}>
      <nav
        aria-label={labels.navigation}
        data-slot="pagination"
        className={cn(
          "mx-auto flex w-full flex-wrap items-center justify-between gap-3 text-sm",
          className,
        )}
        {...props}
      >
        {children === undefined ? (
          <>
            <PaginationInfo />
            <PaginationControls />
          </>
        ) : (
          children
        )}
      </nav>
    </PaginationContext.Provider>
  );
}

type PaginationInfoProps = Omit<React.ComponentProps<"div">, "children"> & {
  children?: React.ReactNode | ((info: PaginationRangeInfo) => React.ReactNode);
};

function PaginationInfo({
  className,
  children,
  ...props
}: PaginationInfoProps) {
  const context = usePagination();
  const { page, perPage, totalCount, pageCount, from, to } = context;
  const info = { page, perPage, totalCount, pageCount, from, to };
  return (
    <div
      data-slot="pagination-info"
      aria-live="polite"
      aria-atomic="true"
      className={cn("text-muted-foreground text-sm tabular-nums", className)}
      {...props}
    >
      {typeof children === "function"
        ? children(info)
        : (children ?? context.labels.range(info))}
    </div>
  );
}

/** `glass` and `frosted` make the controls one capsule, like ButtonGroup. */
type PaginationControlsProps = React.ComponentProps<"div"> &
  GlassProps & {
    controls?: PaginationControlsMode;
    pageSelector?: "input" | "dropdown";
  };

function PaginationControls({
  className,
  controls,
  pageSelector = "input",
  glass,
  frosted,
  ...props
}: PaginationControlsProps) {
  const context = usePagination();
  const {
    page,
    pageCount,
    disabled,
    labels,
    canPrevious,
    canNext,
    changePage,
  } = context;
  const full =
    (controls ?? context.controls) === "full" && pageCount !== undefined;
  const unavailable = disabled || context.totalCount === 0;
  const [editing, setEditing] = React.useState({
    page,
    pageCount,
    value: String(page),
    dirty: false,
  });
  const currentDraft = editing.page === page && editing.pageCount === pageCount;
  if (!currentDraft) {
    setEditing({ page, pageCount, value: String(page), dirty: false });
  }
  const draft = currentDraft ? editing.value : String(page);
  function reset() {
    setEditing({ page, pageCount, value: String(page), dirty: false });
  }
  function commit(value: string) {
    if (!currentDraft || !editing.dirty) return;
    const number = /^\d+$/.test(value.trim()) ? Number(value) : Number.NaN;
    const target = Number.isFinite(number)
      ? Math.min(Math.max(number, 1), pageCount ?? page)
      : page;
    setEditing({ page, pageCount, value: String(page), dirty: false });
    changePage(target);
  }
  // Dropdowns are for small page counts; large datasets keep a bounded input.
  const dropdown = pageSelector === "dropdown" && (pageCount ?? 0) <= 200;
  return (
    <div
      data-slot="pagination-controls"
      className={cn("flex shrink-0 items-center", className)}
      {...props}
    >
      <ButtonGroup
        aria-label={labels.navigation}
        glass={glass}
        frosted={frosted}
      >
        {full && (
          <Button
            type="button"
            variant="outline"
            size="icon"
            data-variant="outline"
            className={paginationControlClassName}
            aria-label={labels.firstPage}
            disabled={!canPrevious}
            onClick={() => changePage(1)}
          >
            <ChevronFirstIcon className="rtl:rotate-180" />
          </Button>
        )}
        <Button
          type="button"
          variant="outline"
          size="icon"
          data-variant="outline"
          className={paginationControlClassName}
          aria-label={labels.previousPage}
          disabled={!canPrevious}
          onClick={() => changePage(page - 1)}
        >
          <ChevronLeftIcon className="rtl:rotate-180" />
        </Button>
        {full &&
          (dropdown ? (
            <Select
              value={page}
              disabled={unavailable}
              onValueChange={(next) => {
                if (next !== null) changePage(next);
              }}
            >
              <SelectTrigger
                className={cn(
                  paginationControlClassName,
                  "h-9 w-fit min-w-14 justify-center gap-1 px-2",
                )}
                aria-label={labels.pageNumber}
              >
                <SelectValue>{page}</SelectValue>
              </SelectTrigger>
              <SelectContent>
                <SelectList>
                  {Array.from(
                    { length: pageCount ?? 1 },
                    (_, index) => index + 1,
                  ).map((number) => (
                    <SelectItem key={number} value={number}>
                      {number}
                    </SelectItem>
                  ))}
                </SelectList>
              </SelectContent>
            </Select>
          ) : (
            <Input
              type="text"
              inputMode="numeric"
              pattern="[0-9]*"
              aria-label={labels.pageNumber}
              className={cn(
                paginationControlClassName,
                "h-9 w-14 flex-none px-2 text-center tabular-nums",
              )}
              value={draft}
              disabled={unavailable}
              autoComplete="off"
              onChange={(event) =>
                setEditing({
                  page,
                  pageCount,
                  value: event.target.value,
                  dirty: true,
                })
              }
              onBlur={(event) => commit(event.currentTarget.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter") {
                  event.preventDefault();
                  commit(event.currentTarget.value);
                } else if (event.key === "Escape") {
                  event.preventDefault();
                  event.stopPropagation();
                  reset();
                }
              }}
            />
          ))}
        <Button
          type="button"
          variant="outline"
          size="icon"
          data-variant="outline"
          className={paginationControlClassName}
          aria-label={labels.nextPage}
          disabled={!canNext}
          onClick={() => changePage(page + 1)}
        >
          <ChevronRightIcon className="rtl:rotate-180" />
        </Button>
        {full && (
          <Button
            type="button"
            variant="outline"
            size="icon"
            data-variant="outline"
            className={paginationControlClassName}
            aria-label={labels.lastPage}
            disabled={!canNext}
            onClick={() => changePage(pageCount ?? page)}
          >
            <ChevronLastIcon className="rtl:rotate-180" />
          </Button>
        )}
      </ButtonGroup>
    </div>
  );
}

/** `glass` and `frosted` apply to the size select's trigger and menu. */
type PaginationPageSizeProps = Omit<React.ComponentProps<"div">, "onChange"> &
  GlassProps & {
    value: number;
    onValueChange: (value: number) => void;
    options?: readonly number[];
    label?: React.ReactNode;
    disabled?: boolean;
  };

function PaginationPageSize({
  value,
  onValueChange,
  options = [10, 20, 50, 100],
  label = "Rows per page",
  disabled = false,
  glass,
  frosted,
  className,
  ...props
}: PaginationPageSizeProps) {
  const context = usePagination();
  const id = React.useId();
  const size = safeInteger(value, context.perPage, 1);
  const sizes = [
    ...new Set([
      size,
      ...options.filter((option) => Number.isSafeInteger(option) && option > 0),
    ]),
  ].sort((a, b) => a - b);
  return (
    <div
      data-slot="pagination-page-size"
      className={cn("flex items-center gap-2", className)}
      {...props}
    >
      {label !== null && (
        <Label htmlFor={id} className="font-normal text-muted-foreground">
          {label}
        </Label>
      )}
      <Select
        value={size}
        disabled={disabled || context.disabled}
        onValueChange={(next) => {
          if (next !== null) onValueChange(next);
        }}
      >
        <SelectTrigger
          id={id}
          glass={glass}
          frosted={frosted}
          aria-label={context.labels.pageSize}
          className={cn(paginationControlClassName, "w-fit min-w-18")}
        >
          <SelectValue>{size}</SelectValue>
        </SelectTrigger>
        <SelectContent glass={glass} frosted={frosted}>
          <SelectList>
            {sizes.map((number) => (
              <SelectItem key={number} value={number}>
                {number}
              </SelectItem>
            ))}
          </SelectList>
        </SelectContent>
      </Select>
    </div>
  );
}

function PaginationSeparator({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      data-slot="pagination-separator"
      orientation={orientation}
      className={cn("h-6 data-vertical:self-center", className)}
      {...props}
    />
  );
}

function PaginationContentImplementation({
  className,
  ...props
}: React.ComponentProps<"ul">) {
  return (
    <ul
      data-slot="pagination-content"
      className={cn(
        "mx-auto flex glass:w-fit items-center gap-1 glass:rounded-4xl glass:p-1",
        className,
      )}
      {...props}
    />
  );
}
function PaginationItem(props: React.ComponentProps<"li">) {
  return <li data-slot="pagination-item" {...props} />;
}

type PaginationLinkProps = { isActive?: boolean; disabled?: boolean } & Pick<
  VariantProps<typeof buttonVariants>,
  "size"
> &
  React.ComponentProps<"a">;

function PaginationLink({
  className,
  isActive,
  size = "icon",
  disabled = false,
  href,
  onClick,
  tabIndex,
  ...props
}: PaginationLinkProps) {
  const context = React.useContext(PaginationContext);
  const unavailable =
    disabled ||
    context?.disabled ||
    props["aria-disabled"] === true ||
    props["aria-disabled"] === "true";
  return (
    <a
      {...props}
      href={unavailable ? undefined : href}
      tabIndex={unavailable ? -1 : tabIndex}
      aria-disabled={unavailable || undefined}
      aria-current={isActive ? "page" : undefined}
      data-slot="pagination-link"
      data-active={isActive}
      className={cn(
        buttonVariants({ variant: isActive ? "default" : "ghost", size }),
        "aria-disabled:cursor-not-allowed aria-disabled:opacity-50",
        className,
      )}
      onClick={(event) => {
        if (unavailable) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClick?.(event);
      }}
    />
  );
}
function PaginationPrevious({
  className,
  text = "Previous",
  ...props
}: React.ComponentProps<typeof PaginationLink> & { text?: string }) {
  const context = React.useContext(PaginationContext);
  return (
    <PaginationLink
      aria-label={context?.labels.previousPage ?? defaultLabels.previousPage}
      size="default"
      className={cn("ps-2!", className)}
      {...props}
    >
      <ChevronLeftIcon data-icon="inline-start" className="rtl:rotate-180" />
      <span className="hidden sm:block">{text}</span>
    </PaginationLink>
  );
