type ThemeVariant = "rectangle" | "circle" | "circle-blur" | "blinds";
type ThemeRevealStart =
  | "button"
  | "top-left"
  | "top-right"
  | "bottom-left"
  | "bottom-right"
  | "center"
  | "bottom-up";
type ThemeToggleProps = Omit<
  ComponentProps<typeof Button>,
  "children" | "variant"
> & {
