      data-slot="toast-close"
      aria-label="Close toast"
      render={render}
      className={cn(
        "relative shrink-0 text-muted-foreground after:absolute after:-inset-2 after:content-[''] hover:text-foreground",
        className,
      )}
      {...props}
    >
      {children ?? <XIcon aria-hidden="true" />}
    </ToastPrimitive.Close>
  );
}

function ToastIcon({ type }: { type: string | undefined }) {
  let icon: React.ReactNode = null;

  if (type === "success") {
    icon = <CircleCheckIcon aria-hidden="true" />;
  }

  if (type === "info") {
    icon = <InfoIcon aria-hidden="true" />;
  }

  if (type === "warning") {
    icon = <TriangleAlertIcon aria-hidden="true" />;
  }

  if (type === "error") {
    icon = <OctagonXIcon aria-hidden="true" />;
  }

  if (type === "loading") {
    icon = <Loader2Icon className="animate-spin" aria-hidden="true" />;
  }

  if (!icon) {
    return null;
  }

  return (
    <span
      data-slot="toast-icon"
      className="shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none"
    >
      {icon}
    </span>
  );
}

const notificationHaptics: Partial<Record<string, HapticKind>> = {
  success: "success",
  warning: "warning",
  error: "error",
};

function ToastList({
  side = "top",
  glass,
  frosted,
  feedback,
}: { side?: "top" | "bottom"; feedback?: FeedbackOption } & GlassProps) {
  const { toasts } = ToastPrimitive.useToastManager();
  const trigger = useFeedback(feedback);
  // Each toast taps once per status it reaches, so a promise toast that
  // settles from loading into success or error still reports the outcome.
  const notified = React.useRef(new Map<string, string | undefined>());
  React.useEffect(() => {
    const seen = notified.current;
    const live = new Set<string>();
    for (const item of toasts) {
      live.add(item.id);
      if (seen.has(item.id) && seen.get(item.id) === item.type) continue;
      seen.set(item.id, item.type);
      const kind = item.type && notificationHaptics[item.type];
      if (kind) trigger(kind);
    }
    for (const id of seen.keys()) if (!live.has(id)) seen.delete(id);
  }, [toasts, trigger]);

  return toasts.map((toastItem) => (
    <Toast
      key={toastItem.id}
      toast={toastItem}
      glass={glass}
      frosted={frosted}
      data-type={toastItem.type}
      // Dismiss toward the nearest edge or sideways.
      swipeDirection={side === "top" ? ["up", "right"] : ["down", "right"]}
    >
      <ToastContent>
        <ToastIcon type={toastItem.type} />
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <ToastTitle />
          <ToastDescription />
        </div>
        <ToastAction />
        <ToastClose />
      </ToastContent>
    </Toast>
  ));
}

function Toaster({
  children,
  toastManager = toast,
  position = "top-center",
  colorful = true,
  glass,
  frosted,
  feedback,
  ...props
}: ToastPrimitive.Provider.Props &
  GlassProps & {
    /** Haptics for success, warning and error toasts. */
    feedback?: FeedbackOption;
    /** Where toasts appear; top center by default. */
    position?: ToastPosition;
    /** Tints success, info, warning and error toasts with their status color. */
    colorful?: boolean;
  }) {
  return (
    <ToastProvider toastManager={toastManager} {...props}>
      {children}
      <ToastPortal>
        <ToastViewport position={position} colorful={colorful}>
          <ToastList
            side={toastSide(position)}
            glass={glass}
            frosted={frosted}
            feedback={feedback}
          />
        </ToastViewport>
      </ToastPortal>
    </ToastProvider>
  );
}

