import type { Options as ReactMarkdownOptions } from "react-markdown";
import { defaultSchema } from "rehype-sanitize";
import remarkBreaks from "remark-breaks";
import remarkGfm from "remark-gfm";
import remarkMath from "remark-math";
import remarkToc from "remark-toc";

export interface MarkdownNode {
  type?: string;
  depth?: number;
  url?: string;
  properties?: Record<string, unknown>;
  lang?: string;
  value?: string;
  data?: Record<string, unknown>;
  children?: MarkdownNode[];
}

/** GitHub alert types and their default titles. */
export const alertTitles = {
  note: "Note",
  tip: "Tip",
  important: "Important",
  warning: "Warning",
  caution: "Caution",
};

export type AlertType = keyof typeof alertTitles;

const alertTypes = /^(?:note|tip|important|warning|caution)$/;

// Raw HTML keeps the GitHub defaults; only what the remark plugins emit is
// added. Classes stay restricted, so content cannot apply app utilities such
// as `fixed inset-0` to cover the page.
export const sanitizeSchema = {
  ...defaultSchema,
  attributes: {
    ...defaultSchema.attributes,
    code: [["className", /^language-./, "math-inline", "math-display"]],
    div: [
      ...(defaultSchema.attributes?.div ?? []),
      [
        "className",
        /^markdown-alert(?:-title)?(?:-(?:note|tip|important|warning|caution))?$/,
      ],
      ["dataAlert", alertTypes],
    ],
    // Task list checkboxes only, which may be checked.
    input: [["disabled", true], ["type", "checkbox"], "checked"],
    td: [["align", "left", "center", "right"]],
    th: [["align", "left", "center", "right"]],
  },
};

export const markdownRemarkPlugins: ReactMarkdownOptions["remarkPlugins"] = [
  remarkGfm,
  remarkViewerHeadingIds,
  [remarkToc, { heading: "contents|table[ -]of[ -]contents|toc", tight: true }],
  remarkBreaks,
  remarkMath,
  remarkMathCodeBlocks,
  remarkGitHubAlerts,
];

/**
 * While a reply streams in, its last code fence may still be open. Closing
 * it lets that block render as code instead of swallowing the text after it.
 */
export function closeOpenFence(content: string) {
  const fences = content.match(/^ {0,3}(`{3,}|~{3,})/gm) ?? [];
  if (fences.length % 2 === 0) return content;
  const marker = fences[fences.length - 1].trim();
  return `${content.replace(/\n?$/, "\n")}${marker}`;
}
function remarkMathCodeBlocks() {
  return (tree: MarkdownNode) => {
    walkMarkdownNode(tree, (node) => {
      if (node.type !== "code" || node.lang !== "math") return;
      node.type = "math";
      node.lang = undefined;
    });
  };
}

function remarkGitHubAlerts() {
  return (tree: MarkdownNode) => {
    walkMarkdownNode(tree, (node) => {
      if (node.type !== "blockquote") return;

      const firstParagraph = node.children?.[0];
      const firstText = firstParagraph?.children?.[0];
      if (
        firstParagraph?.type !== "paragraph" ||
        firstText?.type !== "text" ||
        !firstText.value
      ) {
        return;
      }

      const match = firstText.value.match(
        /^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)]\s*\n?/i,
      );
      if (!match) return;

      const type = match[1].toLowerCase() as AlertType;
      if (!(type in alertTitles)) return;

      firstText.value = firstText.value
        .slice(match[0].length)
        .replace(/^\s+/, "");
      while (
        firstParagraph.children?.[0] &&
        isEmptyAlertLeadNode(firstParagraph.children[0])
      ) {
        firstParagraph.children.shift();
      }
      if (firstParagraph.children?.length === 0) {
        node.children?.shift();
      }
      node.data = {
        hName: "div",
        hProperties: {
          className: `markdown-alert markdown-alert-${type}`,
          dataAlert: type,
        },
      };
      node.children?.unshift({
        type: "paragraph",
        data: {
          hName: "div",
          hProperties: {
            className: `markdown-alert-title markdown-alert-title-${type}`,
          },
        },
        children: [{ type: "text", value: alertTitles[type] }],
      });
    });
  };
}

function isEmptyAlertLeadNode(node: MarkdownNode) {
  return (
    (node.type === "text" && (node.value ?? "").trim().length === 0) ||
    node.type === "break"
  );
}

export function walkMarkdownNode(
  node: MarkdownNode,
  visitor: (node: MarkdownNode) => void,
) {
  visitor(node);
  if (!node.children) return;
  for (const child of node.children) {
    walkMarkdownNode(child, visitor);
  }
}

export function slugify(value: string) {
  const slug = value
    .toLowerCase()
    .trim()
    .replace(/[^\w\u4e00-\u9fa5\s-]/g, "")
    .replace(/\s+/g, "-");
  return slug || "section";
}

function markdownNodeText(node: MarkdownNode): string {
  return node.value ?? node.children?.map(markdownNodeText).join("") ?? "";
}
function remarkViewerHeadingIds() {
  return (tree: MarkdownNode) => {
    const used = new Map<string, number>();
    walkMarkdownNode(tree, (node) => {
      if (node.type !== "heading") return;
      const slug = slugify(markdownNodeText(node));
      const occurrence = used.get(slug) ?? 0;
      used.set(slug, occurrence + 1);
      node.data = {
        ...node.data,
        hProperties: {
          ...((node.data?.hProperties as object) ?? {}),
          id: occurrence ? `${slug}-${occurrence}` : slug,
        },
      };
    });
  };
}
export function rehypeViewerAnchors({ prefix }: { prefix: string }) {
  return (tree: MarkdownNode) => {
    const ids = new Map<string, string>();
    const used = new Set<string>();
    walkMarkdownNode(tree, (node) => {
      const props = node.properties;
      if (!props) return;
      for (const property of ["id", "name"])
        if (typeof props[property] === "string") {
          const previous = props[property];
          let next = `${prefix}-${previous}`;
          let duplicate = 1;
          while (used.has(next)) next = `${prefix}-${previous}-${duplicate++}`;
          used.add(next);
          props[property] = next;
          if (!ids.has(previous)) ids.set(previous, next);
          const original = previous.replace(/^(user-content-)+/, "");
          if (!ids.has(original)) ids.set(original, next);
        }
    });
    walkMarkdownNode(tree, (node) => {
      const props = node.properties;
      if (!props) return;
      if (typeof props.href === "string" && props.href.startsWith("#")) {
        const target = ids.get(props.href.slice(1));
        if (target) props.href = `#${target}`;
      }
      for (const property of ["ariaDescribedBy", "ariaLabelledBy"]) {
        const value = props[property];
        if (Array.isArray(value))
          props[property] = value.map((id) =>
            typeof id === "string" ? (ids.get(id) ?? id) : id,
          );
        else if (typeof value === "string")
          props[property] = value
            .split(/\s+/)
            .map((id) => ids.get(id) ?? id)
            .join(" ");
      }
    });
  };
}

"use client";

import { cn } from "cn";
import { useId, useMemo, useRef } from "react";
import ReactMarkdown, {
  type Components,
  type Options as ReactMarkdownOptions,
} from "react-markdown";
import rehypeRaw from "rehype-raw";
import rehypeSanitize from "rehype-sanitize";
import { ImageGroup } from "@/components/ui/image";
import { useColorScheme } from "@/hooks/use-color-scheme";
import { MarkdownContext, markdownComponents } from "@/components/viewers/markdown/components";
import type { MarkdownViewerLabels } from "@/components/viewers/markdown/labels";
import {
  closeOpenFence,
  markdownRemarkPlugins,
  rehypeViewerAnchors,
  sanitizeSchema,
} from "@/components/viewers/markdown/plugins";

type PluginList = NonNullable<ReactMarkdownOptions["remarkPlugins"]>;

export interface MarkdownViewerProps {
  content: string;
  theme?: "light" | "dark";
  className?: string;
  labels?: Partial<MarkdownViewerLabels>;
  /** `streaming` tolerates an unfinished last block and marks it as writing. */
  status?: "streaming" | "complete";
  /** Added after the built-in remark plugins. */
  remarkPlugins?: PluginList;
  /**
   * Added after raw HTML parsing and before sanitizing, which always runs
   * last. Extend output through `components` rather than new attributes.
   */
  rehypePlugins?: PluginList;
  /** Element renderers merged over the built-in ones, e.g. `img` or `a`. */
  components?: Components;
}

const NO_PLUGINS: PluginList = [];

export function MarkdownViewer({
  content,
  theme,
  className,
  labels,
  status,
  remarkPlugins = NO_PLUGINS,
  rehypePlugins = NO_PLUGINS,
  components,
}: Readonly<MarkdownViewerProps>) {
  const rootRef = useRef<HTMLDivElement>(null);
  const headingPrefix = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const { resolvedTheme: appTheme } = useColorScheme(rootRef);
  const resolvedTheme = theme ?? appTheme;

  const streaming = status === "streaming";
  const source = streaming ? closeOpenFence(content) : content;
  const streamingEnd = streaming ? source.trimEnd().length : undefined;
  const elements = useMemo(
    () => ({ ...markdownComponents, ...components }),
    [components],
  );

  if (!content.trim()) {
    return (
      <div className={cn("text-muted-foreground text-sm", className)}>
        {labels?.empty ?? "No markdown content"}
      </div>
    );
  }

  return (
    <MarkdownContext
      value={{ headingPrefix, theme: resolvedTheme, labels, streamingEnd }}
    >
      <div
        ref={rootRef}
        data-slot="markdown-viewer"
        className={cn(
          "max-w-none text-foreground text-sm",
          // Only an explicit override owns a local theme boundary. Mirroring
          // the inherited theme here would make the observer read its own output.
          theme === "dark" && "dark",
          "[&_.contains-task-list]:list-none [&_.contains-task-list]:pl-0 [&_.task-list-item]:my-1 [&_.task-list-item]:flex [&_.task-list-item]:items-start [&_.task-list-item]:gap-2 [&_.task-list-item_input]:mt-1",
          "[&_.footnotes]:mt-10 [&_.footnotes]:border-t [&_.footnotes]:pt-4 [&_.footnotes]:text-sm",
          className,
        )}
      >
        <ImageGroup labels={labels?.image}>
          <ReactMarkdown
            remarkPlugins={[...(markdownRemarkPlugins ?? []), ...remarkPlugins]}
            rehypePlugins={[
              rehypeRaw,
              ...rehypePlugins,
              [rehypeSanitize, sanitizeSchema],
              [rehypeViewerAnchors, { prefix: headingPrefix }],
            ]}
            remarkRehypeOptions={{ clobberPrefix: `${headingPrefix}-` }}
            components={elements}
          >
            {source}
          </ReactMarkdown>
        </ImageGroup>
      </div>
    </MarkdownContext>
  );
}

"use client";

import { cn } from "cn";
import { AlertCircle, LoaderCircle } from "lucide-react";

/**
 * The writing / loading / error line in a viewer header. Once content is
 * ready the line disappears; screen readers still hear that it finished.
 */
export function ViewerStatus({
  streaming,
  loading,
  failed,
  reducedMotion,
  labels,
}: {
  streaming: boolean;
  loading: boolean;
  failed: boolean;
  reducedMotion: boolean | null;
  labels: { writing: string; loading: string; ready: string; error: string };
}) {
  let state: keyof typeof labels = "ready";
  if (failed) state = "error";
  else if (streaming) state = "writing";
  else if (loading) state = "loading";
  if (state === "ready")
    return (
      <span role="status" className="sr-only">
        {labels.ready}
      </span>
    );
  const Icon = {
    error: AlertCircle,
    writing: LoaderCircle,
    loading: LoaderCircle,
  }[state];
  const color = {
    error: "text-destructive",
    writing: "text-primary",
    loading: "text-primary",
  }[state];
  return (
    <span
      role="status"
      className={cn(
        "inline-flex shrink-0 items-center gap-1 font-medium text-sm",
        color,
      )}
    >
      <Icon
        aria-hidden="true"
        className={cn(
          "size-3.5",
          (streaming || loading) && !failed && !reducedMotion && "animate-spin",
        )}
      />
      {labels[state]}
    </span>
  );
}

import {
  type RefObject,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { useShikiThemes } from "@/lib/highlight/provider";
import type { ThemedToken } from "@/lib/highlight/shiki";

const EMPTY_LINES: ThemedToken[][] = [];

type HighlightResult = Readonly<{
  key: string;
  lines: ThemedToken[][];
  failed: boolean;
}>;

export function useHighlightedLines(
  code: string,
  lang: string,
  theme: "light" | "dark",
) {
  const themes = useShikiThemes();
  const key = `${lang}\u0000${theme}\u0000${themes.light}\u0000${themes.dark}\u0000${code}`;
  const [result, setResult] = useState<HighlightResult | null>(null);

  useEffect(() => {
    if (!code) return;
    let active = true;
    import("@/lib/highlight/shiki")
      .then(({ codeToTokens }) => codeToTokens(code, lang, theme, themes))
      .then((lines) => {
        if (active) setResult({ key, lines, failed: false });
      })
      .catch(() => {
        if (active) setResult({ key, lines: [], failed: true });
      });
    return () => {
      active = false;
    };
  }, [code, key, lang, theme, themes]);

  const current = result?.key === key ? result : null;
  return {
    lines: current?.lines ?? EMPTY_LINES,
    failed: current?.failed ?? false,
    loading: Boolean(code) && !current,
  };
}

export function useStreamingScroll(
  viewportRef: RefObject<HTMLDivElement | null>,
  content: string,
  streaming: boolean,
) {
  const followRef = useRef(true);
  const lastScrollTop = useRef(0);
  const wasStreaming = useRef(streaming);
  const updateFollow = useCallback((viewport: HTMLDivElement) => {
    const top = viewport.scrollTop;
    // Scroll notifications may arrive after new content changes the bottom.
    // An unchanged position is not a reader choosing to scroll away.
    if (top === lastScrollTop.current) return;
    lastScrollTop.current = top;
    followRef.current =
      viewport.scrollHeight - viewport.clientHeight - top <= 32;
  }, []);
  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    if (streaming) followRef.current = true;
    lastScrollTop.current = viewport.scrollTop;
    const onScroll = () => updateFollow(viewport);
    viewport.addEventListener("scroll", onScroll, { passive: true });
    return () => viewport.removeEventListener("scroll", onScroll);
  }, [streaming, viewportRef, updateFollow]);
  useEffect(() => {
    const viewport = viewportRef.current;
    const completing = wasStreaming.current && !streaming;
    wasStreaming.current = streaming;
    if (
      (!streaming && !completing) ||
      !content ||
      !viewport ||
      !followRef.current
    )
      return;
    const frame = requestAnimationFrame(() => {
      updateFollow(viewport);
      if (!followRef.current || viewport.scrollHeight <= viewport.clientHeight)
        return;
      viewport.scrollTo({
        top: viewport.scrollHeight,
        behavior: "instant",
      });
      lastScrollTop.current = viewport.scrollTop;
    });
    return () => cancelAnimationFrame(frame);
  }, [content, streaming, viewportRef, updateFollow]);
}
